#!/usr/bin/env python3
"""Generate ``results/README.md`` -- the map of every tracked file under results/.

2026-09-03 (improvement backlog, "results/ needs the data/ treatment"). Same discipline as
``build_data_readme.py``: every tracked file must be covered by an entry in ``DESCRIPTIONS``
and every entry must still match something, so the map cannot drift. Entries are exact
paths, directories (covering everything beneath) or glob patterns (``*`` / ``?``), because
the frozen wave records come in families of a dozen files.

The one thing this README exists to say, per family: who WRITES it and who READS it. A file
nothing reads is either history (say so) or an orphan (archive it under results/legacy_lane).

Run inside Docker:
    python scripts/generators/build_results_readme.py           # write results/README.md
    python scripts/generators/build_results_readme.py --check   # exit 1 if stale
"""
from __future__ import annotations

import argparse
import fnmatch
import subprocess
import sys
from collections import defaultdict
from pathlib import Path
from typing import Dict, List, Optional, Tuple

ROOT = Path(__file__).resolve().parents[2]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from src import data_paths  # noqa: E402

SKIP_BASENAMES = {".DS_Store"}
OUTPUT = data_paths.RESULTS_ROOT / "README.md"

